$newPaths = @(
    "E:\path\arm-gcc\arm-gnu-toolchain-13.2.Rel1-mingw-w64-i686-arm-none-eabi\bin",
    "E:\path\cmake\cmake-3.30.3-windows-x86_64\bin",
    "E:\path\ninja",
    "E:\path\sftool",
    "E:\path\C_C++\mingw64\bin",
    "E:\path\java\bin",
    "E:\path\Flutter\bin"
)

$currentPath = [Environment]::GetEnvironmentVariable("PATH", "Machine")
$pathsToAdd = $newPaths | Where-Object { $currentPath -notlike "*$_*" }

if ($pathsToAdd.Count -gt 0) {
    $newPath = $currentPath + ";" + ($pathsToAdd -join ";")
    [Environment]::SetEnvironmentVariable("PATH", $newPath, "Machine")
    Write-Host "✅ 已添加以下路径到系统 PATH：" -ForegroundColor Green
    $pathsToAdd | ForEach-Object { Write-Host "  + $_" }
} else {
    Write-Host "ℹ️ 所有路径已存在于 PATH 中" -ForegroundColor Yellow
}

$newPaths = @(
    "E:\path\arm-gcc\arm-gnu-toolchain-13.2.Rel1-mingw-w64-i686-arm-none-eabi\bin",
    "E:\path\cmake\cmake-3.30.3-windows-x86_64\bin",
    "E:\path\ninja",
    "E:\path\sftool",
    "E:\path\C_C++\mingw64\bin",
    "E:\path\java\bin",
    "E:\path\Flutter\bin"
)

$currentPath = [Environment]::GetEnvironmentVariable("PATH", "User")
$pathsToAdd = $newPaths | Where-Object { $currentPath -notlike "*$_*" }

if ($pathsToAdd.Count -gt 0) {
    $newPath = if ($currentPath) { $currentPath + ";" + ($pathsToAdd -join ";") } else { $pathsToAdd -join ";" }
    [Environment]::SetEnvironmentVariable("PATH", $newPath, "User")
    Write-Host "✅ 已添加到用户 PATH：" -ForegroundColor Green
    $pathsToAdd | ForEach-Object { Write-Host "  + $_" }
    Write-Host ""
    Write-Host "⚠️ 请重启终端或注销后生效" -ForegroundColor Yellow
} else {
    Write-Host "ℹ️ 所有路径已存在于 PATH 中" -ForegroundColor Yellow
}
